    /// <summary>Glyph capacity of one predefined charset (validation bound for nGlyphs).</summary>
    internal static int CharsetLength(int predefined) => predefined switch
    {
        0 => IsoAdobeGlyphCount,
        1 => ExpertGlyphCount,
        2 => ExpertSubsetGlyphCount,
        _ => 0
    };

    /// <summary>Glyph-ordered SID sequence of one predefined charset.</summary>
    internal static ushort[] Charset(int predefined) => predefined switch
    {
        0 => IsoAdobeCharset,
        1 => ExpertCharset,
        _ => ExpertSubsetCharset
    };

    /// <summary>Code-indexed SID map of one predefined encoding; 0 means "no code assigned".</summary>
    internal static int EncodingSid(int predefined, int code) =>
        (uint)code > 0xFF ? 0 : (predefined == 0 ? StandardEncoding : ExpertEncoding)[code];

